if(prefs.motion===undefined)prefs.motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const main=$('#main'), icon=(name,cls='')=>`<span class="icon ${cls}" data-icon="${name}" aria-hidden="true"></span>`, done=l=>state.completed.includes(l.id), count=c=>c.lessons.filter(done).length;
