function home(){return `<section class="hero"><div class="hero-copy"><p class="eyebrow">EDUCAÇÃO FINANCEIRA PARA COMEÇAR</p><h1>Dinheiro se<br>aprende mexendo<span>.</span></h1><p class="hero-intro">Escolha um assunto, teste uma decisão<br>e entenda o que muda.</p><div class="hero-links"><a class="text-link" href="#aula/comeco/0">Começar pelo orçamento ${icon('arrow-up-right')}</a><a class="secondary-link" href="#experimentar">Já quero experimentar</a></div></div><figure class="ascii-figure"><div class="ascii-stage" id="ascii-stage"><img src="assets/ascii-art-source.png" alt="Folha tridimensional de caracteres, com pequenos detalhes azuis e laranja." id="ascii-fallback"><canvas id="ascii-canvas" hidden role="img" aria-label="Uma folha de caracteres que muda de perspectiva com o ponteiro. É uma composição visual interativa."></canvas></div><figcaption><span>Mova para ver outra perspectiva</span><button class="plain-button" id="ascii-pause" aria-pressed="false">${icon('pause')}<span>Pausar movimento</span></button></figcaption></figure></section><section class="case-strip"><div><p class="eyebrow">UM CASO PARA COMEÇAR · EXEMPLO FICTÍCIO</p><h2>Entraram R$ 600. Para onde eles vão?</h2><p>Monte um mês possível antes de estudar o conceito.</p></div><div class="case-actions"><div class="case-token">${icon('bus')}<div><span>Transporte</span><b>R$ 120</b></div></div><div class="case-token">${icon('game-controller')}<div><span>Lazer</span><b>R$ 80</b></div></div><a class="button" href="#experimentar/caso">Abrir o exercício ${icon('arrow-right')}</a></div></section><section class="home-after" aria-label="Primeiras trilhas">${COURSES.slice(0,2).map((c,i)=>courseRow(c,i)).join('')}<div class="section-tail"><span>12 trilhas. No seu ritmo.</span><a href="#aprender">Explorar todos os assuntos ${icon('arrow-right')}</a></div></section>${state.last?`<section class="section-tail"><span>${state.completed.length} de ${TOTAL} aulas concluídas neste navegador.</span><a href="#aula/${state.last.replace(':','/')}">Continuar de onde parei ${icon('arrow-up-right')}</a></section>`:''}`}
function learning(){return `<div class="page"><div class="page-head"><p class="eyebrow">APRENDER · 12 TRILHAS / 48 AULAS</p><h1>Entenda antes<br>de decidir<span class="accent">.</span></h1><p class="lead">Do dinheiro do dia a dia aos investimentos. Explicações, contas comentadas e atividades para colocar o raciocínio em prática.</p><div class="progress-line"><span style="width:${state.completed.length/TOTAL*100}%"></span></div><p class="progress-caption">${state.completed.length} de ${TOTAL} aulas concluídas · salvo neste navegador</p></div><label class="search">${icon('magnifying-glass')}<input type="search" id="course-search" placeholder="Qual assunto você quer entender?" aria-label="Buscar trilhas"></label><div id="course-results">${courseResults('')}</div><p class="fine">O tempo indicado é uma estimativa de leitura e prática. Não há prazo para terminar.</p></div>`}
function courseResults(query){const q=normalize(query),groups=MODULES.map(m=>{const list=m.ids.map(course).filter(c=>normalize(c.title+' '+c.desc+' '+c.lessons.map(l=>l.title).join(' ')).includes(q));return list.length?`<section><div class="section-heading"><h2>${E(m.name)}</h2><span>${list.length} trilhas</span></div><p class="fine">${E(m.description)}</p>${list.map(c=>courseRow(c,COURSES.indexOf(c))).join('')}</section>`:''});return groups.join('')||'<p class="empty">Nenhuma trilha encontrada. Tente “orçamento”, “juros” ou “risco”.</p>'}
function coursePage(c){return `<div class="page"><nav class="breadcrumb" aria-label="Você está aqui"><a href="#aprender">Aprender</a><span>/</span><span>${E(c.title)}</span></nav><div class="page-head"><p class="eyebrow">TRILHA ${String(COURSES.indexOf(c)+1).padStart(2,'0')} · ${c.lessons.length} AULAS</p><h1>${E(c.title)}<span class="accent">.</span></h1><p class="lead">${E(c.desc)}</p><div class="progress-line"><span style="width:${count(c)/c.lessons.length*100}%"></span></div><p class="progress-caption">${count(c)} de ${c.lessons.length} aulas concluídas</p></div>${c.lessons.map((l,i)=>`<a class="course-row" href="#aula/${c.id}/${i}"><span class="row-number">${String(i+1).padStart(2,'0')}</span><span class="row-title">${E(l.title)}<span class="row-desc">${E(l.intro)}</span></span><span class="row-meta">${done(l)?'Concluída':`${l.minutes} min · ${l.activities.length} atividades`}</span>${icon(done(l)?'check':'arrow-up-right','row-arrow')}</a>`).join('')}<div class="section-tail"><a href="#experimentar">Testar uma simulação ${icon('arrow-up-right')}</a><a href="#aprender">Outras trilhas ${icon('arrow-right')}</a></div></div>`}
function answerKey(l,j){return `${l.id}:${j}`}
function answerState(l,j){const k=answerKey(l,j);return state.answers[k]&&typeof state.answers[k]==='object'?state.answers[k]:{}}
function allPassed(l){return l.activities.every((a,j)=>answerState(l,j).pass===true)}
